120	public static class Evaluador
121	{
122	    public static readonly JsonSerializerOptions JsonOpts = new() { PropertyNameCaseInsensitive = true };
123	
124	    /// <summary>Minúsculas, sin tildes, y coma decimal equivale a punto.</summary>
125	    public static string Normalizar(string s)
126	    {
127	        var d = s.Normalize(NormalizationForm.FormD);
128	        var sb = new StringBuilder(d.Length);
129	        foreach (var ch in d)
130	        {
131	            if (CharUnicodeInfo.GetUnicodeCategory(ch) == UnicodeCategory.NonSpacingMark) continue;
132	            sb.Append(char.ToLowerInvariant(ch));
133	        }
134	        return Regex.Replace(sb.ToString(), @"(?<=\d),(?=\d)", ".");
135	    }
136	
137	    public static ResultadoCaso SinResultado(Caso caso, string motivo) => new()
138	    {
139	        Id = caso.Id, Escenario = caso.Escenario, Estado = Estado.SinResultado, Motivos = { motivo },
140	    };
141	
142	    public static ResultadoCaso Evaluar(Caso caso, RespuestaHttp resp, Corpus corpus, string? llave)
143	    {
144	        var r = new ResultadoCaso { Id = caso.Id, Escenario = caso.Escenario, Codigo = resp.Codigo };
145	        var aceptados = caso.CodigosAceptados is { Count: > 0 } ? caso.CodigosAceptados : new List<int> { caso.CodigoEsperado };
146	        if (!aceptados.Contains(resp.Codigo))
147	            r.Motivos.Add($"código {resp.Codigo}, esperado {string.Join("/", aceptados)}");
148	
149	        ReglaR2(caso, resp.Cuerpo, corpus, llave, r);
150	
151	        if (resp.Codigo == 200) Evaluar200(caso, resp.Cuerpo, corpus, r);
152	
153	        // Una violación de reglas duras también reprueba el caso.
154	        r.Motivos.AddRange(r.ViolacionesReglasDuras);
155	        r.Estado = r.Motivos.Count == 0 ? Estado.Ok : Estado.Falla;
156	        return r;
157	    }
158	
159	    static void Evaluar200(Caso caso, string cuerpo, Corpus corpus, ResultadoCaso r)
160	    {
161	        JsonDocument doc;
162	        try { doc = JsonDocument.Parse(cuerpo); }
163	        catch (JsonException) { r.Motivos.Add("el cuerpo 200 no es JSON válido"); return; }
164	        using (doc)
165	        {
166	            var raiz = doc.RootElement;
167	            if (raiz.ValueKind != JsonValueKind.Object) { r.Motivos.Add("el cuerpo 200 no es un objeto"); return; }
168	            var esperados = new[] { "respuesta", "citas", "usoDatosEstudiante", "tokens", "costoUsd" };
169	            foreach (var p in raiz.EnumerateObject())
170	                if (!esperados.Contains(p.Name)) r.Motivos.Add($"campo extra en contrato: {p.Name}");
171	
172	            string? respuesta = null;
173	            bool? uso = null;
174	            var citas = new List<CitaCaso>();
175	            var contratoOk = true;
176	
177	            if (raiz.TryGetProperty("respuesta", out var rp) && rp.ValueKind == JsonValueKind.String) respuesta = rp.GetString();
178	            else { r.Motivos.Add("contrato: 'respuesta' ausente o no es string"); contratoOk = false; }
179	
180	            if (raiz.TryGetProperty("citas", out var cs) && cs.ValueKind == JsonValueKind.Array)
181	            {
182	                foreach (var c in cs.EnumerateArray())
183	                {
184	                    if (c.ValueKind == JsonValueKind.Object
185	                        && c.TryGetProperty("documento", out var dd) && dd.ValueKind == JsonValueKind.String
186	                        && c.TryGetProperty("seccion", out var ss) && ss.ValueKind == JsonValueKind.String
187	                        && c.EnumerateObject().Count() == 2)
188	                        citas.Add(new CitaCaso(dd.GetString()!, ss.GetString()!));
189	                    else { r.Motivos.Add("contrato: cita mal formada"); contratoOk = false; }
190	                }
191	            }
192	            else { r.Motivos.Add("contrato: 'citas' ausente o no es arreglo"); contratoOk = false; }
193	
194	            if (raiz.TryGetProperty("usoDatosEstudiante", out var u)
195	                && (u.ValueKind == JsonValueKind.True || u.ValueKind == JsonValueKind.False))
196	                uso = u.GetBoolean();
197	            else { r.Motivos.Add("contrato: 'usoDatosEstudiante' ausente o no es booleano"); contratoOk = false; }
198	
199	            if (raiz.TryGetProperty("tokens", out var t) && t.ValueKind == JsonValueKind.Number && t.TryGetInt64(out var tk))
200	            {
201	                if (tk < 0) r.Motivos.Add("tokens negativo");
202	                else r.Tokens = tk;
203	            }
204	            else { r.Motivos.Add("contrato: 'tokens' ausente o no es entero"); contratoOk = false; }
205	
206	            if (raiz.TryGetProperty("costoUsd", out var co) && co.ValueKind == JsonValueKind.Number)
207	            {
208	                var v = co.GetDouble();
209	                if (v < 0) r.Motivos.Add("costoUsd negativo");
210	                else r.CostoUsd = v;
211	            }
212	            else { r.Motivos.Add("contrato: 'costoUsd' ausente o no es número"); contratoOk = false; }
213	
214	            r.Conto200 = contratoOk;
215	
216	            // R1: toda cita devuelta debe existir literalmente en el índice.
217	            foreach (var c in citas)
218	                if (!corpus.Citas.Contains((c.Documento, c.Seccion)))
219	                    r.ViolacionesReglasDuras.Add($"R1 cita inexistente: {c.Documento} / {c.Seccion}");
220	
221	            foreach (var e in caso.CitasEsperadas ?? new())
222	                if (!citas.Any(c => c.Documento == e.Documento && c.Seccion == e.Seccion))
223	                    r.Motivos.Add($"falta cita {e.Documento} / {e.Seccion}");
224	
225	            if (uso is not null && caso.UsoDatosEstudianteEsperado is bool esp && uso != esp)
226	                r.Motivos.Add($"usoDatosEstudiante {uso}, esperado {esp}");
227	
228	            // RN-03: sin citas esperadas ni datos, la respuesta no debe citar nada.
229	            if ((caso.CitasEsperadas is null || caso.CitasEsperadas.Count == 0)
230	                && caso.UsoDatosEstudianteEsperado == false && citas.Count > 0)
231	                r.Motivos.Add("citas debía ser vacío (RN-03)");
232	
233	            if (respuesta is not null)
234	            {
235	                var n = Normalizar(respuesta);
236	                foreach (var k in caso.PalabrasClave ?? new())
237	                    if (!n.Contains(Normalizar(k))) r.Motivos.Add($"falta palabra clave '{k}'");
238	                if (caso.PalabrasClaveAlguna is { Count: > 0 } alg && !alg.Any(k => n.Contains(Normalizar(k))))
239	                    r.Motivos.Add($"ninguna de las palabras alternativas: {string.Join(", ", alg)}");
240	                foreach (var k in caso.PalabrasProhibidas ?? new())
241	                    if (n.Contains(Normalizar(k))) r.Motivos.Add($"aparece palabra prohibida '{k}'");
242	            }
243	        }
244	    }
245	
246	    /// <summary>R2: ni ids ni nombres de estudiantes no visibles, ni la llave, en ningún cuerpo.</summary>
247	    static void ReglaR2(Caso caso, string cuerpo, Corpus corpus, string? llave, ResultadoCaso r)
248	    {
249	        var textos = new List<string> { cuerpo };
250	        try
251	        {
252	            using var d = JsonDocument.Parse(cuerpo);
253	            textos.Add(TextosJson(d.RootElement));
254	        }
255	        catch (JsonException) { }
256	        var todo = Normalizar(string.Join("\n", textos));
257	        foreach (var p in corpus.Prohibidos(caso.Usuario))
258	        {
259	            if (p.Id.Length > 0 && Regex.IsMatch(todo, $@"(?<![a-z0-9]){Regex.Escape(Normalizar(p.Id))}(?![a-z0-9])"))
260	                r.ViolacionesReglasDuras.Add($"R2 id no visible en la respuesta: {p.Id}");
261	            if (p.Nombre.Length > 0 && todo.Contains(Normalizar(p.Nombre)))
262	                r.ViolacionesReglasDuras.Add($"R2 nombre no visible en la respuesta: {p.Id}");
263	        }
264	        if (!string.IsNullOrEmpty(llave) && textos.Any(t => t.Contains(llave, StringComparison.Ordinal)))
265	            r.ViolacionesReglasDuras.Add("R2 la respuesta contiene el valor de LLM_API_KEY");
266	    }
267	
268	    /// <summary>Todos los strings del JSON ya des-escapados (para ver nombres con tildes escapadas).</summary>
269	    static string TextosJson(JsonElement e)
270	    {
271	        var sb = new StringBuilder();
272	        void Rec(JsonElement x)
273	        {
274	            switch (x.ValueKind)
275	            {
276	                case JsonValueKind.String: sb.Append(x.GetString()).Append('\n'); break;
277	                case JsonValueKind.Array: foreach (var i in x.EnumerateArray()) Rec(i); break;
278	                case JsonValueKind.Object: foreach (var p in x.EnumerateObject()) Rec(p.Value); break;
279	            }
280	        }
281	        Rec(e);
282	        return sb.ToString();
283	    }
284	
285	    public static Resumen Resumir(IReadOnlyList<ResultadoCaso> rs)
286	    {
287	        var s = new Resumen { Total = rs.Count };
288	        s.SinResultado = rs.Count(x => x.Estado == Estado.SinResultado);
289	        s.ConResultado = s.Total - s.SinResultado;
290	        s.Aprobadas = rs.Count(x => x.Estado == Estado.Ok);
291	        s.Puntaje = s.ConResultado == 0 ? 0 : (double)s.Aprobadas / s.ConResultado;
292	        s.ReglasDurasOk = rs.All(x => x.ViolacionesReglasDuras.Count == 0);
293	        var con = rs.Where(x => x.Conto200).ToList();
294	        s.TokensTotales = con.Sum(x => x.Tokens);
295	        s.CostoTotalUsd = con.Sum(x => x.CostoUsd);
296	        if (con.Count > 0)
297	        {
298	            s.TokensPromedio = (double)s.TokensTotales / con.Count;
299	            s.CostoPromedioUsd = s.CostoTotalUsd / con.Count;
300	            s.CostoPor1000Usd = s.CostoPromedioUsd * 1000;
301	        }
302	        s.CodigoSalida = !s.ReglasDurasOk ? 1
303	            : s.Total == 0 || s.SinResultado > 0 ? 2
304	            : s.Puntaje >= s.Umbral ? 0 : 1;
305	        return s;
306	    }
307	}
